UPDATE daily_tasks SET task_title='OLT-001 [Task] Single-client step 1: remove SaaS layer and pin oltao tenant', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S0 (pre-kickoff) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the delivery team, I want the ERP running in single-client mode for the oltao tenant, so that SaaS plans, billing and tenant switching never reach the client.</p><h4>Acceptance criteria</h4><ul><li>&#9745; SINGLE_CLIENT_SLUG pins the oltao tenant</li><li>&#9745; Plans, subscriptions and tenant switcher hidden from all screens</li><li>&#9745; Test suite green after the change</li><li>&#9745; Steps documented in docs/single-client</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Merged (PR #9). Step 2 (drop tenant_id) deferred.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Single-client step 1: remove SaaS layer and pin oltao tenant';
UPDATE daily_tasks SET task_title='OLT-002 [Task] Get Proposal v3 (Annexure 1) and check sections 5-7 against the plan', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S0-S1 (pre-kickoff to wk 1) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want Proposal v3 (Annexure 1) checked against the delivery plan, so that nothing in sections 5-7 (binding under Cl. 2.2) is missing from the roadmap.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Proposal v3 received from client</li><li>&#9744; Every feature in sections 5, 6, 7 mapped to a stage and ticket</li><li>&#9744; Gaps logged as new tickets or Change Requests</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 2.2 makes Proposal sections 5, 6 and 7 binding.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Get Proposal v3 (Annexure 1) and check sections 5-7 against the plan';
UPDATE daily_tasks SET task_title='OLT-003 [Task] Settle contract points with client and lawyer (roadmap vs Schedule B, ownership, SLA start, delay terms)', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S0-S1 (pre-kickoff to wk 1) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> OLT-002</p><h4>User story</h4><p>As the project manager, I want the contract points settled with the client and lawyer, so that the fixed-price terms are deliverable.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Roadmap attached as a Schedule or replaces Schedule B (Cl. 30.1, 6.2)</li><li>&#9744; Pre-existing platform listed in Schedule A with licence (Cl. 11.3)</li><li>&#9744; SLA start date and on-call scope agreed (Schedule C)</li><li>&#9744; Deemed acceptance and delay terms negotiated (Cl. 6.3, 20.3)</li><li>&#9744; Lawyer review notes on file</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>See Oltao ERP Delivery Plan section 4.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Settle contract points with client and lawyer (roadmap vs Schedule B, ownership, SLA start, delay terms)';
UPDATE daily_tasks SET task_title='OLT-004 [Task] Fill Schedules A (pre-existing tools), D, E, F and the Contract Price', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S0-S1 (pre-kickoff to wk 1) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> OLT-003</p><h4>User story</h4><p>As the project manager, I want Schedules A, D, E, F and the Contract Price filled, so that the agreement can be signed.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Schedule A: pre-existing tools listed</li><li>&#9744; Schedule D: client inputs incl. outside approvals</li><li>&#9744; Schedules E/F: team and key people named</li><li>&#9744; Contract Price includes on-call and warranty cost</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Fill Schedules A (pre-existing tools), D, E, F and the Contract Price';
UPDATE daily_tasks SET task_title='OLT-005 [Task] Create client-owned GitHub org, cloud, vault; push the repository', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S0-S1 (pre-kickoff to wk 1) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> OLT-008</p><h4>User story</h4><p>As the technical lead, I want a client-owned GitHub org, cloud account and vault, so that all code sits in the client repository from day one (Cl. 11.5).</p><h4>Acceptance criteria</h4><ul><li>&#9744; GitHub org owned by Nine Oasis, team invited</li><li>&#9744; Cloud and vault in client name; no secrets in code</li><li>&#9744; Repository pushed after scope clean-up</li><li>&#9744; Daily push routine agreed</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clauses 11.5, 12.1, 12.2: nothing registered in Warrgyizmorsch\'s name.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Create client-owned GitHub org, cloud, vault; push the repository';
UPDATE daily_tasks SET task_title='OLT-006 [Task] Collect signed confidentiality and IP undertakings from every team member', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S0-S1 (pre-kickoff to wk 1) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want signed confidentiality and IP undertakings from each team member, so that access is granted lawfully (Cl. 19.5).</p><h4>Acceptance criteria</h4><ul><li>&#9744; Undertaking signed by every person before access</li><li>&#9744; Copies stored in project documents</li><li>&#9744; Access list matches signed list</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 19.5</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Collect signed confidentiality and IP undertakings from every team member';
UPDATE daily_tasks SET task_title='OLT-007 [Task] Set up CI: tests, static analysis, licence check', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S0-S1 (pre-kickoff to wk 2) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> OLT-005</p><h4>User story</h4><p>As the technical lead, I want CI with tests, static analysis and a licence check, so that every push is verified (Cl. 11.4).</p><h4>Acceptance criteria</h4><ul><li>&#9744; CI runs PHPUnit + Larastan on every PR</li><li>&#9744; Licence check fails on disallowed licences</li><li>&#9744; Staging deploy from main is green</li><li>&#9744; Badge/status visible in repo</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 11.4 - no GPL/AGPL.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Set up CI: tests, static analysis, licence check';
UPDATE daily_tasks SET task_title='OLT-008 [Task] Decide HRMS: remove or hide before first push to client repo', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S0-S1 (pre-kickoff to wk 1) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the technical lead, I want a decision on HRMS code (remove or hide), so that out-of-scope code is not handed over in the first push.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Decision recorded as ADR</li><li>&#9744; PayrollAccountingService dependency handled</li><li>&#9744; Out-of-scope modules removed or hidden before push</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>PayrollAccountingService touches payroll - remove with care.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Decide HRMS: remove or hide before first push to client repo';
UPDATE daily_tasks SET task_title='OLT-101 [Task] Shopify call audit + 22 apps audit', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S1 (wk 1-2) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the technical lead, I want every Shopify call and the 22 installed apps audited, so that each one has a matching ERP endpoint or replacement.</p><h4>Acceptance criteria</h4><ul><li>&#9745; Search: myshopify, storefront, cartCreate, checkoutUrl, customerAccount, metafield</li><li>&#9745; Each call mapped to an ERP endpoint</li><li>&#9745; Each of 22 apps marked replace / drop / keep</li><li>&#9745; docs/stage-1.1/shopify-audit.md signed off</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>docs/stage-1.1/shopify-audit.md</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Shopify call audit + 22 apps audit';
UPDATE daily_tasks SET task_title='OLT-102 [Task] Storefront API contract (OpenAPI) and Postman collection', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S1 (wk 1-2) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> OLT-101</p><h4>User story</h4><p>As the Next.js developer, I want an OpenAPI storefront contract and Postman collection, so that the store can be repointed without guessing.</p><h4>Acceptance criteria</h4><ul><li>&#9745; OpenAPI for /api/storefront/v1 complete</li><li>&#9745; Error format, auth, pagination and idempotency documented</li><li>&#9745; Postman collection runs against staging</li><li>&#9745; Contract frozen after sign-off</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>docs/stage-1.1/storefront-api-contract.md</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Storefront API contract (OpenAPI) and Postman collection';
UPDATE daily_tasks SET task_title='OLT-103 [Task] Architecture and database schema document', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S1-S2 (wk 1-3) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> OLT-101</p><h4>User story</h4><p>As the technical lead, I want the architecture and database schema documented, so that new modules (Commerce, Logistics, Channels, Service, Dealer) follow one design.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Domain layout under app/Domains agreed</li><li>&#9744; ER diagram for new tables</li><li>&#9744; Group entities modelled as companies under one tenant (Cl. 4.2)</li><li>&#9744; Event flows between modules described</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Architecture and database schema document';
UPDATE daily_tasks SET task_title='OLT-104 [Task] DPDP design: consent, retention, data-processor duties, breach notice', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S1-S2 (wk 2-3) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the data protection owner, I want a DPDP design, so that consent, retention and breach duties are built in.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Consent capture and withdrawal flows</li><li>&#9744; Retention periods per data type</li><li>&#9744; Data-processor duties and sub-processor list</li><li>&#9744; Breach notice procedure</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clauses 4.5, 13</p>', updated_at=NOW() WHERE project_id=@p AND task_title='DPDP design: consent, retention, data-processor duties, breach notice';
UPDATE daily_tasks SET task_title='OLT-105 [Task] Shopify + Odoo migration map and rollback plan', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S1-S2 (wk 2-3) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> OLT-101, OLT-103</p><h4>User story</h4><p>As the technical lead, I want a Shopify + Odoo migration map and rollback plan, so that cutover is reversible.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Field-level map for products, customers, orders, stock</li><li>&#9744; Record-count and money-total reconciliation method</li><li>&#9744; Rollback: repoint storefront to Shopify, kept 30 days</li><li>&#9744; Odoo bridge cut-off dates per stage</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 15.2</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Shopify + Odoo migration map and rollback plan';
UPDATE daily_tasks SET task_title='OLT-106 [Task] Test plan and UAT approach per stage', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S1-S2 (wk 2-3) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the QA lead, I want a test plan and UAT approach per stage, so that acceptance is objective.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Test types per stage (unit, API, E2E, load, security)</li><li>&#9744; UAT sheet template with pass/fail</li><li>&#9744; Defect severities mapped to Schedule C</li><li>&#9744; Entry/exit criteria per stage</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Use qa-test-plan skill.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Test plan and UAT approach per stage';
UPDATE daily_tasks SET task_title='OLT-107 [Task] Wireframes: OTP login, customer dashboard, dealer portal outline', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S1-S2 (wk 2-3) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the UX designer, I want wireframes for OTP login, customer dashboard and dealer portal, so that the client approves flows before build.</p><h4>Acceptance criteria</h4><ul><li>&#9744; OTP login + account wireframes</li><li>&#9744; Customer dashboard v1 and full version</li><li>&#9744; Dealer portal outline</li><li>&#9744; Client feedback recorded</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Wireframes: OTP login, customer dashboard, dealer portal outline';
UPDATE daily_tasks SET task_title='OLT-108 [Task] Send input-request calendar; request week-3 credentials in writing', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S1 (wk 1) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want a dated input-request calendar and written week-3 credential requests, so that late inputs excuse delay (Cl. 6.3, 20.3).</p><h4>Acceptance criteria</h4><ul><li>&#9744; Calendar lists every input with due week</li><li>&#9744; Requests sent at least 10 working days ahead</li><li>&#9744; Week-3 credentials requested: Razorpay, Cashfree, OTP, email, WhatsApp, Meta/GA4/Google Ads</li><li>&#9744; Tracker shared with client</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 20.3: 10 working days ahead.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Send input-request calendar; request week-3 credentials in writing';
UPDATE daily_tasks SET task_title='OLT-109 [Task] ADR-0001: interim invoicing owner + stock/dispatch ownership table weeks 14-27', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S1-S2 (wk 2-3) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> OLT-105</p><h4>User story</h4><p>As the technical lead, I want ADR-0001 deciding the interim invoicing owner and a stock/dispatch ownership table for weeks 14-27, so that ERP and Odoo never both invoice or deduct stock.</p><h4>Acceptance criteria</h4><ul><li>&#9744; One system issues the tax invoice per store order</li><li>&#9744; Ownership table per stage for stock, dispatch, billing</li><li>&#9744; ERP reserves stock at order time; Odoo pull is a correction</li><li>&#9744; Client approval recorded</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Never let ERP and Odoo both invoice the same store order.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='ADR-0001: interim invoicing owner + stock/dispatch ownership table weeks 14-27';
UPDATE daily_tasks SET task_title='OLT-110 [Task] Close open decisions: store GSTIN/series, p95 target, blogs source, 3D model hosting', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S1-S2 (wk 2-3) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want the open decisions closed, so that the build is not blocked.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Store GSTIN and invoice series confirmed</li><li>&#9744; API p95 target fixed (proposed &lt; 300 ms, contract 500 ms)</li><li>&#9744; Blogs source decided (Shopify or ERP)</li><li>&#9744; 3D model file hosting decided</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Close open decisions: store GSTIN/series, p95 target, blogs source, 3D model hosting';
UPDATE daily_tasks SET task_title='OLT-111 [Task] Submit design sign-off pack (release notes, documents)', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S2 (wk 3) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> OLT-102, OLT-103, OLT-104, OLT-105, OLT-106, OLT-107, OLT-109, OLT-110</p><h4>User story</h4><p>As the project manager, I want the design sign-off pack submitted, so that Payment Milestone 1 can be accepted.</p><h4>Acceptance criteria</h4><ul><li>&#9744; All Stage 1.1 documents in one pack</li><li>&#9744; Release notes and acceptance checklist (Cl. 9.1)</li><li>&#9744; Submitted in writing with date</li><li>&#9744; Client sign-off received</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Milestone 1</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Submit design sign-off pack (release notes, documents)';
UPDATE daily_tasks SET task_title='OLT-201 [Story] Catalogue: products, variants, collections, blog, redirects; Shopify import + media rehost', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S2-S3 (wk 4-5) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-102</p><h4>User story</h4><p>As an Oltao operations user, I want products, variants, collections, blog and redirects in the ERP with Shopify import and rehosted media, so that the catalogue lives in one place.</p><h4>Acceptance criteria</h4><ul><li>&#9745; Variants, specs, collections and SEO fields</li><li>&#9745; Shopify import keeps handles and IDs</li><li>&#9745; Media rehosted, no Shopify CDN links</li><li>&#9745; Both bladeless and bladeless-fan collections kept</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Online Store screens; commerce:import-shopify</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Catalogue: products, variants, collections, blog, redirects; Shopify import + media rehost';
UPDATE daily_tasks SET task_title='OLT-202 [Story] Storefront API v1 with keys, idempotency and cursor pagination', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S2-S3 (wk 4-5) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-102</p><h4>User story</h4><p>As the Next.js developer, I want Storefront API v1 with keys, idempotency and cursor pagination, so that the store can call the ERP safely.</p><h4>Acceptance criteria</h4><ul><li>&#9745; API keys per client app</li><li>&#9745; Idempotency-Key honoured on writes</li><li>&#9745; Cursor pagination on lists</li><li>&#9745; Matches the frozen OpenAPI contract</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>/api/storefront/v1</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Storefront API v1 with keys, idempotency and cursor pagination';
UPDATE daily_tasks SET task_title='OLT-203 [Story] Cart with server-side prices, GST by state and coupons; Carts screen', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S2-S3 (wk 4-5) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-202</p><h4>User story</h4><p>As an oltao.in customer, I want a cart with server-side prices, GST by state and coupons, so that totals are always correct.</p><h4>Acceptance criteria</h4><ul><li>&#9745; Prices recalculated server-side</li><li>&#9745; GST split CGST/SGST vs IGST by state</li><li>&#9745; Coupon rules: % / flat / min order / expiry</li><li>&#9745; Abandoned carts visible in admin</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Cart with server-side prices, GST by state and coupons; Carts screen';
UPDATE daily_tasks SET task_title='OLT-204 [Story] Checkout with Cashfree One Click (UPI, cards, Pay Later, EMI) and partial COD', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 13 pts &middot; <strong>Sprint:</strong> S3 (wk 5-6) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-203</p><h4>User story</h4><p>As an oltao.in customer, I want to pay by UPI, card, Pay Later, EMI or partial COD through Cashfree One Click, so that I can check out my way.</p><h4>Acceptance criteria</h4><ul><li>&#9745; Cashfree One Click live in staging</li><li>&#9745; Webhooks idempotent, amounts in paise</li><li>&#9745; Partial COD collects advance online</li><li>&#9745; Failed payment leaves order recoverable</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>PR #4</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Checkout with Cashfree One Click (UPI, cards, Pay Later, EMI) and partial COD';
UPDATE daily_tasks SET task_title='OLT-205 [Story] Duplicate payment flagging, undo unpayable orders, reopen carts', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S3 (wk 5-6) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-204</p><h4>User story</h4><p>As an Oltao operations user, I want duplicate payments flagged, unpayable orders undone and carts reopened, so that money and stock stay consistent.</p><h4>Acceptance criteria</h4><ul><li>&#9745; Duplicate payment flagged for refund</li><li>&#9745; Unpaid order released after timeout</li><li>&#9745; Customer can reopen cart</li><li>&#9745; Audit entry for each action</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>PR #5</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Duplicate payment flagging, undo unpayable orders, reopen carts';
UPDATE daily_tasks SET task_title='OLT-206 [Story] Orders queue (website + Amazon) with filters and Sync now', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S3 (wk 5-6) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-204</p><h4>User story</h4><p>As an Oltao operations user, I want one orders queue for website and Amazon with filters and Sync now, so that I process every channel in one screen.</p><h4>Acceptance criteria</h4><ul><li>&#9745; Channel tag on each order</li><li>&#9745; Filters with reset</li><li>&#9745; Sync now for API marketplaces</li><li>&#9745; Pagination performs on 10k orders</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>PR #7</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Orders queue (website + Amazon) with filters and Sync now';
UPDATE daily_tasks SET task_title='OLT-207 [Story] Audit trail: create/edit/delete/login/export, not editable, 3 years', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S2-S4 (wk 4-7) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the client auditor, I want a tamper-proof audit trail of every create, edit, delete, login and export kept 3 years, so that Cl. 14.1 is met.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Covers create/edit/delete/login/export across modules</li><li>&#9744; Rows cannot be edited or deleted from the app</li><li>&#9744; Retention 3 years</li><li>&#9744; Searchable audit screen</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 14.1 - finish wiring remaining models (docs/audit-trail.md).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Audit trail: create/edit/delete/login/export, not editable, 3 years';
UPDATE daily_tasks SET task_title='OLT-208 [Story] Customer OTP sign-in, saved addresses, My orders', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S3-S4 (wk 6-7) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-202</p><h4>User story</h4><p>As an oltao.in customer, I want to sign in by OTP with saved addresses and My orders, so that I do not need a Shopify password.</p><h4>Acceptance criteria</h4><ul><li>&#9744; OTP via SMS/WhatsApp with rate limit</li><li>&#9744; Saved addresses CRUD</li><li>&#9744; My orders shows migrated old orders</li><li>&#9744; Customer login separate from staff users</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Shopify passwords cannot be exported.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Customer OTP sign-in, saved addresses, My orders';
UPDATE daily_tasks SET task_title='OLT-209 [Story] Razorpay as second gateway, refunds via API', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S3-S4 (wk 6-8) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-204</p><h4>User story</h4><p>As an oltao.in customer, I want Razorpay as a second gateway with API refunds, so that checkout survives a gateway outage.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Razorpay behind the PaymentGateway contract</li><li>&#9744; Admin switch for primary gateway</li><li>&#9744; Refunds via API, partial and full</li><li>&#9744; Webhooks stored, processed once, retried</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Razorpay as second gateway, refunds via API';
UPDATE daily_tasks SET task_title='OLT-210 [Story] COD rules, shipping charges, facet filters (mounting, size, price, availability)', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S3-S4 (wk 6-7) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-203</p><h4>User story</h4><p>As an oltao.in customer, I want COD rules, shipping charges and collection filters, so that I see the right price and can find products.</p><h4>Acceptance criteria</h4><ul><li>&#9744; COD limits by pincode/amount</li><li>&#9744; Shipping charge rules (decision D7)</li><li>&#9744; Facets: mounting, size, price, availability</li><li>&#9744; Filters match current store behaviour</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='COD rules, shipping charges, facet filters (mounting, size, price, availability)';
UPDATE daily_tasks SET task_title='OLT-211 [Story] Two-factor login for admin, staff and dealer accounts', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S3-S4 (wk 6-8) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As an admin, I want two-factor login for admin, staff and dealer accounts, so that Cl. 14.1 is met.</p><h4>Acceptance criteria</h4><ul><li>&#9744; TOTP or OTP second factor</li><li>&#9744; Mandatory for all staff roles</li><li>&#9744; Recovery codes</li><li>&#9744; Login events audited</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 14.1</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Two-factor login for admin, staff and dealer accounts';
UPDATE daily_tasks SET task_title='OLT-212 [Story] Rate limiting, bot protection and fraud checks at login and checkout', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S4 (wk 7-8) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-208</p><h4>User story</h4><p>As the security lead, I want rate limits, bot protection and fraud checks at login and checkout, so that abuse is blocked.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Rate limits on OTP, login, checkout</li><li>&#9744; Bot challenge on suspicious traffic</li><li>&#9744; Fraud rules flag risky COD orders</li><li>&#9744; Blocked events logged</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Rate limiting, bot protection and fraud checks at login and checkout';
UPDATE daily_tasks SET task_title='OLT-213 [Story] Order emails and WhatsApp alerts', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S4 (wk 7-8) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-204</p><h4>User story</h4><p>As an oltao.in customer, I want order emails and WhatsApp alerts, so that I know my order status.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Templates: placed, paid, shipped, delivered, cancelled</li><li>&#9744; WhatsApp templates approved by Meta</li><li>&#9744; Opt-out honoured</li><li>&#9744; Failures retried and logged</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Order emails and WhatsApp alerts';
UPDATE daily_tasks SET task_title='OLT-214 [Story] Meta Pixel + Conversions API, GA4, Google Ads, product feeds (same IDs)', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S4-S5 (wk 7-9) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-204</p><h4>User story</h4><p>As the marketing team, I want Meta Pixel + CAPI, GA4, Google Ads and product feeds with the same IDs, so that ad performance does not drop at cutover.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Purchase event fires on the new thank-you page</li><li>&#9744; Server-side Meta CAPI deduplicated with Pixel</li><li>&#9744; GA4 and Ads conversions verified</li><li>&#9744; Feed product IDs unchanged</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Purchase event moves to the new thank-you page.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Meta Pixel + Conversions API, GA4, Google Ads, product feeds (same IDs)';
UPDATE daily_tasks SET task_title='OLT-215 [Story] Interim Odoo stock pull (queued, idempotent, reconciliation report)', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S4-S5 (wk 8-9) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-109</p><h4>User story</h4><p>As an Oltao operations user, I want an interim Odoo stock pull as a queued idempotent job with a reconciliation report, so that store stock is right until week 20.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Queued job, idempotent, retried</li><li>&#9744; ERP reservations respected</li><li>&#9744; Daily reconciliation report</li><li>&#9744; Switch to turn it off</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Interim Odoo stock pull (queued, idempotent, reconciliation report)';
UPDATE daily_tasks SET task_title='OLT-216 [Task] Daily backups 30 days in separate location + first restore test', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S4-S5 (wk 8-9) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As DevOps, I want daily backups kept 30 days in a separate location with a restore test, so that data is recoverable.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Daily DB + file backups</li><li>&#9744; Stored off the main server</li><li>&#9744; 30-day retention</li><li>&#9744; First restore test documented</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 14.1</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Daily backups 30 days in separate location + first restore test';
UPDATE daily_tasks SET task_title='OLT-217 [Task] Staging UAT: test order per payment method, p95 load check', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S5 (wk 9) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-204, OLT-209, OLT-214</p><h4>User story</h4><p>As the QA lead, I want staging UAT with a test order per payment method and a p95 load check, so that Milestone 2 can be accepted.</p><h4>Acceptance criteria</h4><ul><li>&#9744; One order per method: UPI, card, Pay Later, EMI, COD, partial COD</li><li>&#9744; p95 under target</li><li>&#9744; Conversions visible in Meta and Google</li><li>&#9744; UAT sheet signed</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Staging UAT: test order per payment method, p95 load check';
UPDATE daily_tasks SET task_title='OLT-218 [Task] Submit Milestone 2 release pack', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S5 (wk 9) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-217</p><h4>User story</h4><p>As the project manager, I want the Milestone 2 release pack submitted, so that the 12% payment can be invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Staging build</li><li>&#9744; Release notes</li><li>&#9744; Test results</li><li>&#9744; Acceptance checklist (Cl. 9.1)</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Submit Milestone 2 release pack';
UPDATE daily_tasks SET task_title='OLT-301 [Story] GST tax invoices and credit notes', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S5 (wk 10) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As an Oltao operations user, I want GST tax invoices and credit notes, so that every order is billed compliantly.</p><h4>Acceptance criteria</h4><ul><li>&#9745; Invoice series per GSTIN</li><li>&#9745; CGST/SGST/IGST lines and HSN</li><li>&#9745; Credit note against invoice</li><li>&#9745; PDF matches statutory format</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>PR #10 (built early).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='GST tax invoices and credit notes';
UPDATE daily_tasks SET task_title='OLT-302 [Story] Staff cancel website orders and record refunds', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S5 (wk 10) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-301</p><h4>User story</h4><p>As an Oltao operations user, I want to cancel website orders and record refunds, so that cancellations are tracked.</p><h4>Acceptance criteria</h4><ul><li>&#9745; Cancel with reason</li><li>&#9745; Refund recorded and linked to payment</li><li>&#9745; Stock released</li><li>&#9745; Audit entry</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>PR #8 (built early).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Staff cancel website orders and record refunds';
UPDATE daily_tasks SET task_title='OLT-303 [Task] Migration tools: customers, orders, products; dry run 1 + reconciliation', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S5-S6 (wk 10-11) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-105</p><h4>User story</h4><p>As the technical lead, I want migration tools for customers, orders and products plus dry run 1 with reconciliation, so that problems surface early.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Repeatable import commands</li><li>&#9744; Record counts compared</li><li>&#9744; Money totals compared</li><li>&#9744; Issues logged and fixed</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Migration tools: customers, orders, products; dry run 1 + reconciliation';
UPDATE daily_tasks SET task_title='OLT-304 [Task] Migration dry run 2 + signed reconciliation', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S6 (wk 12) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-303</p><h4>User story</h4><p>As the technical lead, I want dry run 2 with a signed reconciliation, so that cutover data is trusted.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Full dry run on fresh export</li><li>&#9744; Zero unexplained differences</li><li>&#9744; Reconciliation signed by client</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 15.4</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Migration dry run 2 + signed reconciliation';
UPDATE daily_tasks SET task_title='OLT-305 [Story] Carriers: Shiprocket, ShadowFox, Delivery One + manual AWB fallback', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 13 pts &middot; <strong>Sprint:</strong> S5-S6 (wk 10-12) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As an Oltao operations user, I want Shiprocket, ShadowFox and Delivery One with a manual AWB fallback, so that every order can ship.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Adapter per carrier behind one contract</li><li>&#9744; AWB, label, tracking sync</li><li>&#9744; Manual AWB entry fallback</li><li>&#9744; Credentials due week 8</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Carriers: Shiprocket, ShadowFox, Delivery One + manual AWB fallback';
UPDATE daily_tasks SET task_title='OLT-306 [Story] Odoo bridge with three switches (stock in, orders out, accounts export)', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 13 pts &middot; <strong>Sprint:</strong> S5-S6 (wk 10-12) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-109</p><h4>User story</h4><p>As an Oltao operations user, I want an Odoo bridge with three switches (stock in, orders out, accounts export), so that each part retires on its own date.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Three independent switches, no deploy needed</li><li>&#9744; Each call queued, idempotent, retried</li><li>&#9744; Reconciliation report per switch</li><li>&#9744; Never double-invoices (ADR-0001)</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Queued, idempotent, retry, reconciliation report.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Odoo bridge with three switches (stock in, orders out, accounts export)';
UPDATE daily_tasks SET task_title='OLT-307 [Story] Customer dashboard v1', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S6 (wk 11-12) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-208</p><h4>User story</h4><p>As an oltao.in customer, I want a customer dashboard v1, so that I can see orders, invoices and addresses.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Orders with status and tracking</li><li>&#9744; Invoice download</li><li>&#9744; Address book</li><li>&#9744; Mobile friendly</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Customer dashboard v1';
UPDATE daily_tasks SET task_title='OLT-308 [Task] 301 redirects for all existing URLs; fix /products/undefined link', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S6 (wk 11-12) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-201</p><h4>User story</h4><p>As the SEO owner, I want 301 redirects for all existing URLs and the /products/undefined link fixed, so that rankings survive cutover.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Every Shopify URL mapped</li><li>&#9744; 301s tested by crawler</li><li>&#9744; /products/undefined?id=undefined bug fixed</li><li>&#9744; Sitemap updated</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 15.6</p>', updated_at=NOW() WHERE project_id=@p AND task_title='301 redirects for all existing URLs; fix /products/undefined link';
UPDATE daily_tasks SET task_title='OLT-309 [Task] Load test at 5x current peak', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S6 (wk 11-12) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-217</p><h4>User story</h4><p>As DevOps, I want a load test at 5x current peak, so that the store holds sale traffic.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Scenario: browse, cart, checkout</li><li>&#9744; 5x peak sustained</li><li>&#9744; p95 within target</li><li>&#9744; Bottlenecks fixed</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 4.6</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Load test at 5x current peak';
UPDATE daily_tasks SET task_title='OLT-310 [Task] Two-week parallel run with automatic order comparison', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S6-S7 (wk 12-13) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-304, OLT-306</p><h4>User story</h4><p>As the project manager, I want a two-week parallel run with automatic order comparison, so that price, tax, shipping and payment match Shopify.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Daily comparison report per order</li><li>&#9744; Differences triaged within 1 day</li><li>&#9744; Zero open differences at end</li><li>&#9744; Client sign-off</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 15.3</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Two-week parallel run with automatic order comparison';
UPDATE daily_tasks SET task_title='OLT-311 [Task] CERT-In VAPT (finish mid wk 12), fix Critical/High, retest wk 13', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S6-S7 (wk 12-13) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the security lead, I want CERT-In VAPT finished by mid week 12 with Critical/High fixed and retested in week 13, so that the report is ready before cutover.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Auditor testing ends mid week 12</li><li>&#9744; Critical/High fixed</li><li>&#9744; Retest in week 13</li><li>&#9744; Clean report before go/no-go</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 14.2</p>', updated_at=NOW() WHERE project_id=@p AND task_title='CERT-In VAPT (finish mid wk 12), fix Critical/High, retest wk 13';
UPDATE daily_tasks SET task_title='OLT-312 [Task] Rollback rehearsal; on-call rota from week 14', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S7 (wk 13) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-304</p><h4>User story</h4><p>As DevOps, I want a rehearsed rollback and an on-call rota from week 14, so that Schedule C response times are met.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Rollback rehearsed on staging</li><li>&#9744; Repoint-to-Shopify steps timed</li><li>&#9744; On-call rota published</li><li>&#9744; Escalation contacts shared</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Rollback rehearsal; on-call rota from week 14';
UPDATE daily_tasks SET task_title='OLT-313 [Task] Go-live: cutover in low-traffic window (max 2 h downtime)', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S7 (wk 14) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-310, OLT-311, OLT-312</p><h4>User story</h4><p>As the technical lead, I want cutover in a low-traffic window with at most 2 h downtime, so that live orders move to the ERP.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Final delta migrated</li><li>&#9744; Storefront repointed</li><li>&#9744; 301s live</li><li>&#9744; Downtime under 2 hours</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 15.5</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Go-live: cutover in low-traffic window (max 2 h downtime)';
UPDATE daily_tasks SET task_title='OLT-314 [Task] Hypercare: daily checks for 2 weeks; Milestone 3 acceptance', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S7-S8 (wk 14-15) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-313</p><h4>User story</h4><p>As the support team, I want daily checks for two weeks after go-live, so that Milestone 3 is accepted.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Daily checklist run and logged</li><li>&#9744; No Critical/Major open 7 days after cutover</li><li>&#9744; Customers log in by OTP, old orders visible</li><li>&#9744; Milestone 3 acceptance signed</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Hypercare: daily checks for 2 weeks; Milestone 3 acceptance';
UPDATE daily_tasks SET task_title='OLT-401 [Story] Storage locations: warehouse > drawer/rack/shelf/bin', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S8 (wk 16) &middot; <strong>Epic:</strong> Stage 2.1 - Inventory &amp; QR warehouse</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As an Oltao operations user, I want storage locations down to drawer, rack, shelf and bin, so that every unit has an address.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Warehouse &gt; zone &gt; rack &gt; shelf &gt; bin</li><li>&#9744; Multi-warehouse</li><li>&#9744; Import of existing locations</li><li>&#9744; Location on every stock move</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Storage locations: warehouse > drawer/rack/shelf/bin';
UPDATE daily_tasks SET task_title='OLT-402 [Story] QR generation for item, batch and bin + label printing', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S8-S9 (wk 16-17) &middot; <strong>Epic:</strong> Stage 2.1 - Inventory &amp; QR warehouse</p><p><strong>Depends on:</strong> OLT-401</p><h4>User story</h4><p>As an Oltao operations user, I want QR codes for item, batch and bin with label printing, so that stock is scan-driven.</p><h4>Acceptance criteria</h4><ul><li>&#9744; QR per item, batch, bin</li><li>&#9744; Printable label templates</li><li>&#9744; Bulk print</li><li>&#9744; QR resolves to record</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='QR generation for item, batch and bin + label printing';
UPDATE daily_tasks SET task_title='OLT-403 [Story] Mobile scan screens (receive, move, pick, count) in Hindi and English', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 13 pts &middot; <strong>Sprint:</strong> S8-S9 (wk 16-17) &middot; <strong>Epic:</strong> Stage 2.1 - Inventory &amp; QR warehouse</p><p><strong>Depends on:</strong> OLT-402</p><h4>User story</h4><p>As a warehouse worker, I want mobile scan screens to receive, move, pick and count in Hindi and English, so that I work without typing.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Receive, move, pick, count flows</li><li>&#9744; Hindi and English</li><li>&#9744; Works on low-end Android</li><li>&#9744; Offline-tolerant errors</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 4.7</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Mobile scan screens (receive, move, pick, count) in Hindi and English';
UPDATE daily_tasks SET task_title='OLT-404 [Story] Low-stock alerts and live storefront availability', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S9 (wk 17) &middot; <strong>Epic:</strong> Stage 2.1 - Inventory &amp; QR warehouse</p><p><strong>Depends on:</strong> OLT-401</p><h4>User story</h4><p>As an Oltao operations user, I want low-stock alerts and live storefront availability, so that we never oversell.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Reorder level per item/warehouse</li><li>&#9744; Alerts by email/WhatsApp</li><li>&#9744; Storefront stock live from ERP</li><li>&#9744; Reservations respected</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Low-stock alerts and live storefront availability';
UPDATE daily_tasks SET task_title='OLT-405 [Story] Stock count and reconciliation screen', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S9 (wk 17-18) &middot; <strong>Epic:</strong> Stage 2.1 - Inventory &amp; QR warehouse</p><p><strong>Depends on:</strong> OLT-403</p><h4>User story</h4><p>As an Oltao operations user, I want a stock count and reconciliation screen, so that physical and system stock match.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Cycle and full counts</li><li>&#9744; Variance report</li><li>&#9744; Approval before adjustment</li><li>&#9744; Adjustments in stock ledger</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Stock count and reconciliation screen';
UPDATE daily_tasks SET task_title='OLT-406 [Task] Opening stock load and sign-off; retire Odoo stock bridge', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S9 (wk 18) &middot; <strong>Epic:</strong> Stage 2.1 - Inventory &amp; QR warehouse</p><p><strong>Depends on:</strong> OLT-405</p><h4>User story</h4><p>As an Oltao operations user, I want opening stock loaded and signed off, then the Odoo stock bridge retired, so that the ERP owns stock.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Opening stock matches signed count</li><li>&#9744; Odoo stock switch turned off</li><li>&#9744; Storefront reads ERP stock only</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Opening stock load and sign-off; retire Odoo stock bridge';
UPDATE daily_tasks SET task_title='OLT-407 [Task] UAT: full QR cycle; Milestone 4 release pack', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S9 (wk 18) &middot; <strong>Epic:</strong> Stage 2.1 - Inventory &amp; QR warehouse</p><p><strong>Depends on:</strong> OLT-406</p><h4>User story</h4><p>As the QA lead, I want UAT of the full QR cycle and the Milestone 4 release pack, so that 8% can be invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Receive-to-dispatch by scan passes</li><li>&#9744; UAT sheet signed</li><li>&#9744; Release pack submitted</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='UAT: full QR cycle; Milestone 4 release pack';
UPDATE daily_tasks SET task_title='OLT-501 [Story] Configure purchase: suppliers, PO, GRN with QR scan-in, bills', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S10 (wk 19) &middot; <strong>Epic:</strong> Stage 2.2 - Purchase &amp; dispatch</p><p><strong>Depends on:</strong> OLT-402</p><h4>User story</h4><p>As an Oltao operations user, I want suppliers, POs, GRN with QR scan-in and bills, so that purchase flows into stock.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Supplier master</li><li>&#9744; PO approval</li><li>&#9744; GRN by scan</li><li>&#9744; Bill matched to PO/GRN</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Reuse existing module.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Configure purchase: suppliers, PO, GRN with QR scan-in, bills';
UPDATE daily_tasks SET task_title='OLT-502 [Story] Purchase returns and stock transfers', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S10 (wk 19) &middot; <strong>Epic:</strong> Stage 2.2 - Purchase &amp; dispatch</p><p><strong>Depends on:</strong> OLT-501</p><h4>User story</h4><p>As an Oltao operations user, I want purchase returns and stock transfers, so that stock moves are recorded.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Return to supplier with debit note</li><li>&#9744; Inter-warehouse transfer</li><li>&#9744; In-transit status</li><li>&#9744; Ledger entries</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Purchase returns and stock transfers';
UPDATE daily_tasks SET task_title='OLT-503 [Story] Allocation, pick lists and dispatch', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S10 (wk 19-20) &middot; <strong>Epic:</strong> Stage 2.2 - Purchase &amp; dispatch</p><p><strong>Depends on:</strong> OLT-403</p><h4>User story</h4><p>As an Oltao operations user, I want allocation, pick lists and dispatch, so that orders ship from the right bin.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Auto allocation by warehouse rules</li><li>&#9744; Pick list by bin path</li><li>&#9744; Pack and dispatch with AWB</li><li>&#9744; Stock deducted once</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Allocation, pick lists and dispatch';
UPDATE daily_tasks SET task_title='OLT-504 [Story] Courier and customer returns back to stock', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S10 (wk 20) &middot; <strong>Epic:</strong> Stage 2.2 - Purchase &amp; dispatch</p><p><strong>Depends on:</strong> OLT-503</p><h4>User story</h4><p>As an Oltao operations user, I want courier and customer returns back to stock, so that returns restore inventory.</p><h4>Acceptance criteria</h4><ul><li>&#9744; RTO and customer return flows</li><li>&#9744; QC grade on return</li><li>&#9744; Stock restored correctly</li><li>&#9744; Credit note triggered</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Courier and customer returns back to stock';
UPDATE daily_tasks SET task_title='OLT-505 [Story] Reorder suggestions', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S10 (wk 20) &middot; <strong>Epic:</strong> Stage 2.2 - Purchase &amp; dispatch</p><p><strong>Depends on:</strong> OLT-501</p><h4>User story</h4><p>As an Oltao operations user, I want reorder suggestions, so that we buy before stockouts.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Suggest from reorder level and sales velocity</li><li>&#9744; Convert to draft PO</li><li>&#9744; Per warehouse</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Reorder suggestions';
UPDATE daily_tasks SET task_title='OLT-506 [Task] UAT and Milestone 5 release pack', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S10 (wk 20) &middot; <strong>Epic:</strong> Stage 2.2 - Purchase &amp; dispatch</p><p><strong>Depends on:</strong> OLT-503, OLT-504</p><h4>User story</h4><p>As the QA lead, I want UAT and the Milestone 5 release pack, so that 7% can be invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; PO -&gt; stock passes</li><li>&#9744; SO -&gt; dispatch passes</li><li>&#9744; Return -&gt; stock passes</li><li>&#9744; Release pack submitted</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='UAT and Milestone 5 release pack';
UPDATE daily_tasks SET task_title='OLT-601 [Story] Amazon channel listings, FBA warehouse, order report upload', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S11 (wk 21) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As an Oltao operations user, I want Amazon listings, the FBA warehouse and order report upload, so that Amazon stock and orders are in the ERP.</p><h4>Acceptance criteria</h4><ul><li>&#9745; Channel SKU mapping</li><li>&#9745; FBA as a warehouse</li><li>&#9745; Order report upload</li><li>&#9745; Channel tag on orders</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Built early (foundation).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Amazon channel listings, FBA warehouse, order report upload';
UPDATE daily_tasks SET task_title='OLT-602 [Story] Quote -> SO -> invoice chain and credit notes', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S11 (wk 21-22) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As a sales user, I want a quote -&gt; SO -&gt; invoice chain with credit notes, so that B2B sales are traceable.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Quote from CRM converts to SO</li><li>&#9744; SO to delivery to invoice</li><li>&#9744; Credit notes</li><li>&#9744; Document links both ways</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Quote -> SO -> invoice chain and credit notes';
UPDATE daily_tasks SET task_title='OLT-603 [Story] E-invoice IRN + e-way bill per GSTIN (sandbox then live)', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 13 pts &middot; <strong>Sprint:</strong> S11-S12 (wk 21-23) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> OLT-604</p><h4>User story</h4><p>As the accountant, I want e-invoice IRN and e-way bills per GSTIN (sandbox then live), so that billing is compliant.</p><h4>Acceptance criteria</h4><ul><li>&#9744; IRN generated and QR printed</li><li>&#9744; E-way bill above threshold</li><li>&#9744; Cancel within allowed window</li><li>&#9744; Sandbox tested per GSTIN, then live</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 4.1</p>', updated_at=NOW() WHERE project_id=@p AND task_title='E-invoice IRN + e-way bill per GSTIN (sandbox then live)';
UPDATE daily_tasks SET task_title='OLT-604 [Story] Multi-GSTIN invoice series, ledgers, consolidated views', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S11-S12 (wk 22-23) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the accountant, I want invoice series, ledgers and consolidated views per GSTIN, so that each entity is billed separately.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Series per GSTIN</li><li>&#9744; Ledgers per company</li><li>&#9744; Consolidated group view</li><li>&#9744; generateNextInvoiceNumber per GSTIN</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 4.2</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Multi-GSTIN invoice series, ledgers, consolidated views';
UPDATE daily_tasks SET task_title='OLT-605 [Story] Trade accounts: PO-based billing and credit terms', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S12 (wk 23) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> OLT-602</p><h4>User story</h4><p>As a sales user, I want PO-based billing and credit terms for trade accounts, so that dealers can buy on credit.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Credit limit and days per account</li><li>&#9744; Block on overdue</li><li>&#9744; PO number on invoice</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 4.3</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Trade accounts: PO-based billing and credit terms';
UPDATE daily_tasks SET task_title='OLT-606 [Story] Amazon live sync; Flipkart and Myntra order sync; channel reports', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 13 pts &middot; <strong>Sprint:</strong> S11-S12 (wk 22-24) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> OLT-601</p><h4>User story</h4><p>As an Oltao operations user, I want Amazon live sync plus Flipkart and Myntra order sync with channel reports, so that all marketplaces land in one queue.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Amazon SP-API live sync</li><li>&#9744; Flipkart and Myntra order sync</li><li>&#9744; One test order per marketplace in queue</li><li>&#9744; Channel sales report</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Amazon live sync; Flipkart and Myntra order sync; channel reports';
UPDATE daily_tasks SET task_title='OLT-607 [Story] Dealer portal: OTP login, verification, bulk ordering, dashboard', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 13 pts &middot; <strong>Sprint:</strong> S12-S13 (wk 23-25) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> OLT-605</p><h4>User story</h4><p>As a dealer, I want OTP login, verification, bulk ordering and a dashboard, so that I can order without calling.</p><h4>Acceptance criteria</h4><ul><li>&#9744; OTP login and KYC verification</li><li>&#9744; Bulk order with dealer pricing</li><li>&#9744; Orders, invoices, dues dashboard</li><li>&#9744; Full dealer journey passes UAT</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Dealer portal: OTP login, verification, bulk ordering, dashboard';
UPDATE daily_tasks SET task_title='OLT-608 [Task] Retire Odoo order bridge and Odoo billing', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S13 (wk 25) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> OLT-603, OLT-606</p><h4>User story</h4><p>As an Oltao operations user, I want the Odoo order bridge and Odoo billing retired, so that the ERP is the only billing system.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Orders-out switch turned off</li><li>&#9744; Odoo billing stopped</li><li>&#9744; No double invoices</li><li>&#9744; Reconciliation of last Odoo period</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Retire Odoo order bridge and Odoo billing';
UPDATE daily_tasks SET task_title='OLT-609 [Task] UAT and Milestone 6 release pack', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S13 (wk 25) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> OLT-608</p><h4>User story</h4><p>As the QA lead, I want UAT and the Milestone 6 release pack, so that 10% can be invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; E-invoice + e-way per GSTIN pass</li><li>&#9744; One order per marketplace</li><li>&#9744; Dealer full flow</li><li>&#9744; Release pack submitted</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='UAT and Milestone 6 release pack';
UPDATE daily_tasks SET task_title='OLT-701 [Task] Chart of accounts and tax mappings per entity (CA approval)', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S13 (wk 26) &middot; <strong>Epic:</strong> Stage 3.1 - Accounting &amp; finance</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the client CA, I want a chart of accounts and tax mappings per entity, so that books follow our structure.</p><h4>Acceptance criteria</h4><ul><li>&#9744; CoA per company</li><li>&#9744; GST ledgers mapped</li><li>&#9744; CA approval in writing</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 4.8</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Chart of accounts and tax mappings per entity (CA approval)';
UPDATE daily_tasks SET task_title='OLT-702 [Story] Auto-posting from commerce and channels + recovery queue', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S13-S14 (wk 26-27) &middot; <strong>Epic:</strong> Stage 3.1 - Accounting &amp; finance</p><p><strong>Depends on:</strong> OLT-701</p><h4>User story</h4><p>As the accountant, I want auto-posting from commerce and channels with a recovery queue, so that no transaction is missed.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Sales, receipts, refunds, fees auto-post</li><li>&#9744; Failed postings land in recovery queue</li><li>&#9744; Retry and manual fix</li><li>&#9744; Daily posting report</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Auto-posting from commerce and channels + recovery queue';
UPDATE daily_tasks SET task_title='OLT-703 [Story] Bank statement import and reconciliation', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S14 (wk 27) &middot; <strong>Epic:</strong> Stage 3.1 - Accounting &amp; finance</p><p><strong>Depends on:</strong> OLT-701</p><h4>User story</h4><p>As the accountant, I want bank statement import and reconciliation, so that bank and books match.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Statement import (CSV/API)</li><li>&#9744; Auto-match rules</li><li>&#9744; Manual match screen</li><li>&#9744; Reconciliation report</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Bank statement import and reconciliation';
UPDATE daily_tasks SET task_title='OLT-704 [Story] Assets, budgets, financial statements, GSTR-1/3B reports', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S14 (wk 27-28) &middot; <strong>Epic:</strong> Stage 3.1 - Accounting &amp; finance</p><p><strong>Depends on:</strong> OLT-702</p><h4>User story</h4><p>As the accountant, I want assets, budgets, financial statements and GSTR-1/3B reports, so that monthly closing is in the ERP.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Fixed asset register with depreciation</li><li>&#9744; Budgets vs actuals</li><li>&#9744; Trial balance, P&amp;L, balance sheet</li><li>&#9744; GSTR-1 and 3B exports</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Assets, budgets, financial statements, GSTR-1/3B reports';
UPDATE daily_tasks SET task_title='OLT-705 [Story] Tally/Excel export; read-only login for CA and auditor', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S14 (wk 28) &middot; <strong>Epic:</strong> Stage 3.1 - Accounting &amp; finance</p><p><strong>Depends on:</strong> OLT-704</p><h4>User story</h4><p>As the client CA, I want a Tally/Excel export and read-only login for CA and auditor, so that I can review independently.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Tally XML / Excel export</li><li>&#9744; Read-only role</li><li>&#9744; Access audited</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Tally/Excel export; read-only login for CA and auditor';
UPDATE daily_tasks SET task_title='OLT-706 [Task] Opening balances + replay one month of real transactions', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S14 (wk 28) &middot; <strong>Epic:</strong> Stage 3.1 - Accounting &amp; finance</p><p><strong>Depends on:</strong> OLT-702, OLT-703</p><h4>User story</h4><p>As the accountant, I want opening balances loaded and one month of real transactions replayed, so that the books are proven.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Opening balances match signed TB</li><li>&#9744; One month replays cleanly</li><li>&#9744; Differences explained</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Opening balances + replay one month of real transactions';
UPDATE daily_tasks SET task_title='OLT-707 [Task] UAT and Milestone 7 release pack', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S14 (wk 28) &middot; <strong>Epic:</strong> Stage 3.1 - Accounting &amp; finance</p><p><strong>Depends on:</strong> OLT-706</p><h4>User story</h4><p>As the QA lead, I want UAT and the Milestone 7 release pack, so that 8% can be invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; TB, P&amp;L and GST reports verified by accounts approver</li><li>&#9744; Release pack submitted</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='UAT and Milestone 7 release pack';
UPDATE daily_tasks SET task_title='OLT-801 [Story] Leads from website, WhatsApp, Meta Lead Ads; pipeline', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S15 (wk 29) &middot; <strong>Epic:</strong> Stage 3.2 - CRM, warranty &amp; service</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As a sales user, I want leads from website, WhatsApp and Meta Lead Ads in a pipeline, so that no lead is lost.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Meta lead lands automatically</li><li>&#9744; WhatsApp and website forms create leads</li><li>&#9744; Pipeline stages and assignment</li><li>&#9744; Duplicate detection</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Reuse CRM module.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Leads from website, WhatsApp, Meta Lead Ads; pipeline';
UPDATE daily_tasks SET task_title='OLT-802 [Story] Warranty registration, activation and claims', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S15 (wk 29-30) &middot; <strong>Epic:</strong> Stage 3.2 - CRM, warranty &amp; service</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As an oltao.in customer, I want warranty registration, activation and claims, so that service is easy.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Register by serial/QR</li><li>&#9744; Dealer activation</li><li>&#9744; Claim workflow</li><li>&#9744; Warranty status on customer view</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Warranty registration, activation and claims';
UPDATE daily_tasks SET task_title='OLT-803 [Story] Installation and technician screens (VMS API or native)', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 13 pts &middot; <strong>Sprint:</strong> S15-S16 (wk 30-31) &middot; <strong>Epic:</strong> Stage 3.2 - CRM, warranty &amp; service</p><p><strong>Depends on:</strong> OLT-802</p><h4>User story</h4><p>As a technician, I want installation and job screens (VMS API or native), so that installs are scheduled and tracked.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Job assignment</li><li>&#9744; Mobile job screen with photos</li><li>&#9744; VMS API or native per week-4 decision</li><li>&#9744; Customer notified</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Mobile, Hindi + English.</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Installation and technician screens (VMS API or native)';
UPDATE daily_tasks SET task_title='OLT-804 [Story] Support tickets and after-sales', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S16 (wk 31-32) &middot; <strong>Epic:</strong> Stage 3.2 - CRM, warranty &amp; service</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As an oltao.in customer, I want support tickets and after-sales service, so that issues are resolved.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Ticket from web/WhatsApp/call</li><li>&#9744; SLA timers</li><li>&#9744; Linked to order/warranty</li><li>&#9744; Closure feedback</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Support tickets and after-sales';
UPDATE daily_tasks SET task_title='OLT-805 [Story] Customer journeys, MyOperator call logging', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S16 (wk 32) &middot; <strong>Epic:</strong> Stage 3.2 - CRM, warranty &amp; service</p><p><strong>Depends on:</strong> OLT-801</p><h4>User story</h4><p>As the marketing team, I want customer journeys and MyOperator call logging, so that follow-ups are automatic.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Journey triggers and messages</li><li>&#9744; MyOperator calls logged to customer</li><li>&#9744; Recordings linked</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Customer journeys, MyOperator call logging';
UPDATE daily_tasks SET task_title='OLT-806 [Story] Full customer dashboard and unified customer view', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S16-S17 (wk 32-33) &middot; <strong>Epic:</strong> Stage 3.2 - CRM, warranty &amp; service</p><p><strong>Depends on:</strong> OLT-802, OLT-804</p><h4>User story</h4><p>As an oltao.in customer, I want a full customer dashboard and staff a unified customer view, so that the whole history is in one place.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Orders, warranty, installs, tickets in one view</li><li>&#9744; Customer self-service actions</li><li>&#9744; Staff 360 view</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Full customer dashboard and unified customer view';
UPDATE daily_tasks SET task_title='OLT-807 [Task] CRM and warranty migration; retire Odoo', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S17 (wk 33) &middot; <strong>Epic:</strong> Stage 3.2 - CRM, warranty &amp; service</p><p><strong>Depends on:</strong> OLT-806</p><h4>User story</h4><p>As an Oltao operations user, I want CRM and warranty data migrated and Odoo retired, so that one system remains.</p><h4>Acceptance criteria</h4><ul><li>&#9744; CRM and warranty migrated with reconciliation</li><li>&#9744; Odoo access read-only then off</li><li>&#9744; Archive exported</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='CRM and warranty migration; retire Odoo';
UPDATE daily_tasks SET task_title='OLT-808 [Task] UAT and Milestone 8 release pack', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S17 (wk 33) &middot; <strong>Epic:</strong> Stage 3.2 - CRM, warranty &amp; service</p><p><strong>Depends on:</strong> OLT-807</p><h4>User story</h4><p>As the QA lead, I want UAT and the Milestone 8 release pack, so that 10% can be invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Meta lead auto-lands</li><li>&#9744; Unified customer view</li><li>&#9744; Dealer warranty activation</li><li>&#9744; Release pack submitted</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='UAT and Milestone 8 release pack';
UPDATE daily_tasks SET task_title='OLT-901 [Task] Full security test and fixes', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S17-S18 (wk 34-35) &middot; <strong>Epic:</strong> Stage 3.3 - Hardening, handover &amp; Final Acceptance</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the security lead, I want a full security test with fixes, so that no Critical/High remains at handover.</p><h4>Acceptance criteria</h4><ul><li>&#9744; OWASP Top 10 coverage</li><li>&#9744; All modules in scope</li><li>&#9744; Critical/High fixed and retested</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Full security test and fixes';
UPDATE daily_tasks SET task_title='OLT-902 [Task] Performance test', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S17 (wk 34) &middot; <strong>Epic:</strong> Stage 3.3 - Hardening, handover &amp; Final Acceptance</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As DevOps, I want a performance test across modules, so that the system meets targets at handover.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Storefront and back-office scenarios</li><li>&#9744; p95 within target</li><li>&#9744; Report shared</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Performance test';
UPDATE daily_tasks SET task_title='OLT-903 [Story] Reporting dashboards: sales, fulfilment, installation, support', description='<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S17-S18 (wk 34-35) &middot; <strong>Epic:</strong> Stage 3.3 - Hardening, handover &amp; Final Acceptance</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As management, I want dashboards for sales, fulfilment, installation and support, so that I see the business at a glance.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Sales by channel</li><li>&#9744; Fulfilment SLA</li><li>&#9744; Installation and support KPIs</li><li>&#9744; Date and entity filters</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Reporting dashboards: sales, fulfilment, installation, support';
UPDATE daily_tasks SET task_title='OLT-904 [Task] Documentation + manuals in English and Hindi', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S17-S18 (wk 34-36) &middot; <strong>Epic:</strong> Stage 3.3 - Hardening, handover &amp; Final Acceptance</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As a client user, I want documentation and manuals in English and Hindi, so that we can run the system ourselves (Cl. 11.7).</p><h4>Acceptance criteria</h4><ul><li>&#9744; Admin and user manuals per role</li><li>&#9744; Hindi translation</li><li>&#9744; Technical docs and runbooks</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 11.7</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Documentation + manuals in English and Hindi';
UPDATE daily_tasks SET task_title='OLT-905 [Task] Training sessions per role', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S18 (wk 35-36) &middot; <strong>Epic:</strong> Stage 3.3 - Hardening, handover &amp; Final Acceptance</p><p><strong>Depends on:</strong> OLT-904</p><h4>User story</h4><p>As a client user, I want training per role, so that my team is productive.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Sessions per role scheduled</li><li>&#9744; Recordings shared</li><li>&#9744; Attendance recorded</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Training sessions per role';
UPDATE daily_tasks SET task_title='OLT-906 [Task] Credential handover and backup restore test', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S18 (wk 36) &middot; <strong>Epic:</strong> Stage 3.3 - Hardening, handover &amp; Final Acceptance</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the client admin, I want credentials handed over and a backup restore tested, so that we own and can recover the system.</p><h4>Acceptance criteria</h4><ul><li>&#9744; All credentials in client vault</li><li>&#9744; Restore test witnessed</li><li>&#9744; Handover checklist signed</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Credential handover and backup restore test';
UPDATE daily_tasks SET task_title='OLT-907 [Milestone] Final Acceptance UAT and certificate', description='<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S19 (wk 37-38) &middot; <strong>Epic:</strong> Stage 3.3 - Hardening, handover &amp; Final Acceptance</p><p><strong>Depends on:</strong> OLT-901, OLT-902, OLT-904, OLT-905, OLT-906</p><h4>User story</h4><p>As the client, I want Final Acceptance UAT and a certificate, so that the build is formally complete.</p><h4>Acceptance criteria</h4><ul><li>&#9744; All stages accepted</li><li>&#9744; No open Critical/High</li><li>&#9744; Final Acceptance certificate signed (week 38)</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Final Acceptance UAT and certificate';
UPDATE daily_tasks SET task_title='OLT-1001 [Task] Monitor uptime and SLA misses monthly', description='<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S20-S26 (wk 39-51) &middot; <strong>Epic:</strong> Warranty, retention &amp; AMC</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the account manager, I want uptime and SLA misses monitored monthly, so that the warranty period is clean.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Monthly uptime report</li><li>&#9744; SLA misses with root cause</li><li>&#9744; Shared with client</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 17.3</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Monitor uptime and SLA misses monthly';
UPDATE daily_tasks SET task_title='OLT-1002 [Milestone] Raise retention invoice 90 days after Go-Live', description='<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S26 (wk 51) &middot; <strong>Epic:</strong> Warranty, retention &amp; AMC</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the account manager, I want the retention invoice raised 90 days after go-live, so that the final 10% is collected.</p><h4>Acceptance criteria</h4><ul><li>&#9744; No open Critical/Major defects</li><li>&#9744; Retention invoice raised</li><li>&#9744; Payment received</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p><h4>Notes</h4><p>Clause 8.4</p>', updated_at=NOW() WHERE project_id=@p AND task_title='Raise retention invoice 90 days after Go-Live';

