INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=1 LIMIT 1), 'Phase 0', 'OLT-009 [Task] Agree kickoff date, peak sales months and accounting opening-balance date', '2026-10-27', '2026-11-16', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S0-S1 (pre-kickoff to wk 1) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want the kickoff, peak months and opening-balance date agreed, so that cutover and accounting avoid the busy season.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Kickoff date confirmed in writing</li><li>&#9744; Peak fan-sales months confirmed by client</li><li>&#9744; Accounting opening-balance date chosen (FY starts 1 April)</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-009 [Task] Agree kickoff date, peak sales months and accounting opening-balance date');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=1 LIMIT 1), 'Phase 0', 'OLT-010 [Task] Cost on-call rota from week 14 and warranty work into the Contract Price', '2026-10-27', '2026-11-16', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S0-S1 (pre-kickoff to wk 1) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want the on-call and warranty effort costed, so that Schedule C and Cl. 17.2 duties are paid for.</p><h4>Acceptance criteria</h4><ul><li>&#9744; On-call rota cost from week 14 (Critical: 1 h response 24x7)</li><li>&#9744; 10 months of provider API / GST-law updates costed</li><li>&#9744; Included in Contract Price</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-010 [Task] Cost on-call rota from week 14 and warranty work into the Contract Price');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=1 LIMIT 1), 'Phase 0', 'OLT-011 [Milestone] M0 Signing - agreement signed, 10% invoice raised', '2026-11-16', '2026-11-23', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S1 (wk 1-2) &middot; <strong>Epic:</strong> Phase 0 - Pre-kickoff: contract, repo &amp; team</p><p><strong>Depends on:</strong> OLT-003, OLT-004, OLT-010</p><h4>User story</h4><p>As the account manager, I want the agreement signed and the signing invoice raised, so that Payment Milestone 0 (10%) is collected.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Agreement signed by both parties</li><li>&#9744; All Schedules attached</li><li>&#9744; 10% invoice raised and paid</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-011 [Milestone] M0 Signing - agreement signed, 10% invoice raised');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=2 LIMIT 1), 'Stage 1.1', 'OLT-112 [Spike] Confirm reuse vs build list by test, per module (delivery plan section 3)', '2026-11-10', '2026-11-23', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Spike &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S1 (wk 1-2) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the technical lead, I want each Reuse/Extend/Verify item tested, so that estimates rest on facts, not keyword search.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Each section-3 row tested in staging</li><li>&#9744; Status updated: Reuse / Extend / Build</li><li>&#9744; Changes to estimates reported</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-112 [Spike] Confirm reuse vs build list by test, per module (delivery plan section 3)');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=2 LIMIT 1), 'Stage 1.1', 'OLT-113 [Task] Submit Amazon, Flipkart, Myntra seller-API and Meta business verification applications', '2026-11-10', '2026-11-30', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S1-S2 (wk 1-3) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want long-lead applications filed in week 1-3, so that week-18 marketplace credentials arrive on time.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Amazon SP-API developer application</li><li>&#9744; Flipkart and Myntra seller API access requested</li><li>&#9744; Meta business verification started</li><li>&#9744; Status tracked in input calendar</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-113 [Task] Submit Amazon, Flipkart, Myntra seller-API and Meta business verification applications');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=2 LIMIT 1), 'Stage 1.1', 'OLT-114 [Decision] Decide VMS: vendor API usable or native installation build (due week 4, Cl. 2.4)', '2026-11-17', '2026-12-07', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Decision &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S1-S2 (wk 2-4) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want the VMS decision made by week 4, so that Stage 3.2 knows what to build.</p><h4>Acceptance criteria</h4><ul><li>&#9744; VMS vendor API docs and sandbox requested</li><li>&#9744; Decision recorded as ADR by week 4</li><li>&#9744; If no API within 30 days: native build planned</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-114 [Decision] Decide VMS: vendor API usable or native installation build (due week 4, Cl. 2.4)');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=2 LIMIT 1), 'Stage 1.1', 'OLT-115 [Task] Baseline risk register, RAID log and decision (ADR) list', '2026-11-10', '2026-11-16', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S1 (wk 1) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want a RAID log from week 1, so that risks and decisions are visible to the client.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Risks from delivery plan section 4 logged with owner</li><li>&#9744; Assumptions, issues, dependencies listed</li><li>&#9744; ADR index created</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-115 [Task] Baseline risk register, RAID log and decision (ADR) list');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=2 LIMIT 1), 'Stage 1.1', 'OLT-116 [Milestone] M1 Design sign-off - delivered wk 3, accepted wk 5, raise 5% invoice', '2026-11-24', '2026-12-14', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S2-S3 (wk 3-5) &middot; <strong>Epic:</strong> Stage 1.1 - Discovery &amp; design</p><p><strong>Depends on:</strong> OLT-111</p><h4>User story</h4><p>As the account manager, I want design sign-off accepted, so that Payment Milestone 1 (5%) is invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Sign-off pack delivered by week 3</li><li>&#9744; Client acceptance by week 5</li><li>&#9744; 5% invoice raised</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-116 [Milestone] M1 Design sign-off - delivered wk 3, accepted wk 5, raise 5% invoice');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=3 LIMIT 1), 'Stage 1.2', 'OLT-219 [Story] Next.js: repoint catalogue, collection and product pages to the ERP API', '2026-12-08', '2026-12-28', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S3-S4 (wk 5-7) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-201, OLT-202</p><h4>User story</h4><p>As an oltao.in customer, I want product and collection pages served from the ERP, so that the store no longer depends on Shopify.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Products fetched from /api/storefront/v1</li><li>&#9744; Handles and IDs unchanged</li><li>&#9744; 3D viewer, blade-finish preview, specs still work</li><li>&#9744; Facet filters match current behaviour</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-219 [Story] Next.js: repoint catalogue, collection and product pages to the ERP API');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=3 LIMIT 1), 'Stage 1.2', 'OLT-220 [Story] Next.js: cart, checkout and thank-you pages on the ERP API', '2026-12-15', '2027-01-04', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 8 pts &middot; <strong>Sprint:</strong> S3-S4 (wk 6-8) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-219, OLT-204</p><h4>User story</h4><p>As an oltao.in customer, I want cart and checkout on the ERP, so that I pay without Shopify checkout.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Cart and checkout use ERP endpoints</li><li>&#9744; Priority programme add-on supported</li><li>&#9744; Thank-you page fires purchase event (GTM)</li><li>&#9744; Errors shown in the API error format</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-220 [Story] Next.js: cart, checkout and thank-you pages on the ERP API');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=3 LIMIT 1), 'Stage 1.2', 'OLT-221 [Story] Next.js: OTP login and account pages replacing account.oltao.in', '2026-12-22', '2027-01-11', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 5 pts &middot; <strong>Sprint:</strong> S4-S5 (wk 7-9) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-208</p><h4>User story</h4><p>As an oltao.in customer, I want to log in and see my account on oltao.in, so that the Shopify-hosted account site can go.</p><h4>Acceptance criteria</h4><ul><li>&#9744; OTP login pages</li><li>&#9744; My orders and addresses pages</li><li>&#9744; account.oltao.in redirected</li><li>&#9744; Scope confirmed with client</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-221 [Story] Next.js: OTP login and account pages replacing account.oltao.in');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=3 LIMIT 1), 'Stage 1.2', 'OLT-222 [Story] Admin roles and permissions for Oltao staff (reuse AccessService)', '2026-12-01', '2026-12-14', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S2-S3 (wk 4-5) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As an admin, I want roles per Oltao team, so that each user sees only their work.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Roles: admin, ops, warehouse, accounts, support, marketing</li><li>&#9744; Permissions on new Commerce screens</li><li>&#9744; Permission changes audited</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-222 [Story] Admin roles and permissions for Oltao staff (reuse AccessService)');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=3 LIMIT 1), 'Stage 1.2', 'OLT-223 [Story] Packing slip and order print documents', '2026-12-22', '2026-12-28', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Story &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S4 (wk 7) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-301</p><h4>User story</h4><p>As an Oltao operations user, I want packing slips printed per order, so that packers ship the right items.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Packing slip PDF per order</li><li>&#9744; Bulk print from queue</li><li>&#9744; Shows bin locations once Stage 2.1 is live</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-223 [Story] Packing slip and order print documents');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=3 LIMIT 1), 'Stage 1.2', 'OLT-224 [Task] Request week-8 inputs in writing by week 6: Odoo API, carriers, CERT-In auditor', '2026-12-08', '2026-12-14', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S3 (wk 5) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-108</p><h4>User story</h4><p>As the project manager, I want week-8 inputs requested 10 working days ahead, so that late inputs excuse delay (Cl. 20.3).</p><h4>Acceptance criteria</h4><ul><li>&#9744; Odoo API access requested</li><li>&#9744; Shiprocket, ShadowFox, Delivery One credentials requested</li><li>&#9744; CERT-In auditor engagement requested</li><li>&#9744; Requests dated and logged</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-224 [Task] Request week-8 inputs in writing by week 6: Odoo API, carriers, CERT-In auditor');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=3 LIMIT 1), 'Stage 1.2', 'OLT-225 [Task] Book CERT-In auditor: testing ends mid week 12, retest slot in week 13', '2026-12-15', '2026-12-21', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S3 (wk 6) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-224</p><h4>User story</h4><p>As the security lead, I want the auditor booked early, so that the report arrives before the week-14 switch.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Auditor contract signed</li><li>&#9744; Test window fixed: finishes mid week 12</li><li>&#9744; Retest slot booked in week 13</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-225 [Task] Book CERT-In auditor: testing ends mid week 12, retest slot in week 13');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=3 LIMIT 1), 'Stage 1.2', 'OLT-226 [Milestone] M2 Storefront APIs ready - delivered wk 9, accepted wk 11, raise 12% invoice', '2027-01-05', '2027-01-25', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S5-S6 (wk 9-11) &middot; <strong>Epic:</strong> Stage 1.2 - Commerce core &amp; storefront APIs</p><p><strong>Depends on:</strong> OLT-218, OLT-220</p><h4>User story</h4><p>As the account manager, I want Milestone 2 accepted, so that 12% is invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Storefront fully on ERP API in staging</li><li>&#9744; Release pack delivered week 9</li><li>&#9744; Client acceptance week 11</li><li>&#9744; 12% invoice raised</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-226 [Milestone] M2 Storefront APIs ready - delivered wk 9, accepted wk 11, raise 12% invoice');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=4 LIMIT 1), 'Stage 1.3', 'OLT-315 [Task] Go / no-go review for cutover', '2027-02-02', '2027-02-08', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S7 (wk 13) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-310, OLT-311, OLT-312</p><h4>User story</h4><p>As the project manager, I want a formal go/no-go before switching, so that we only cut over when every check is green.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Shopify cutover checklist 1-6 all green</li><li>&#9744; Client and tech lead sign go decision</li><li>&#9744; Low-traffic window confirmed</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-315 [Task] Go / no-go review for cutover');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=4 LIMIT 1), 'Stage 1.3', 'OLT-316 [Task] Keep Shopify as fallback for 30 days, then decommission', '2027-02-09', '2027-03-15', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S7-S9 (wk 14-18) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-313</p><h4>User story</h4><p>As the project manager, I want Shopify kept for 30 days after cutover, so that rollback stays possible.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Shopify plan kept 30 days</li><li>&#9744; Final export archived</li><li>&#9744; Client approves decommission</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-316 [Task] Keep Shopify as fallback for 30 days, then decommission');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=4 LIMIT 1), 'Stage 1.3', 'OLT-317 [Milestone] M3 Shopify cutover - delivered wk 14, accepted wk 15, raise 10% invoice', '2027-02-09', '2027-02-22', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S7-S8 (wk 14-15) &middot; <strong>Epic:</strong> Stage 1.3 - Shopify cutover</p><p><strong>Depends on:</strong> OLT-314</p><h4>User story</h4><p>As the account manager, I want Milestone 3 accepted, so that 10% is invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Live orders on ERP</li><li>&#9744; Reconciliation signed</li><li>&#9744; No Critical/Major open 7 days after</li><li>&#9744; 10% invoice raised</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-317 [Milestone] M3 Shopify cutover - delivered wk 14, accepted wk 15, raise 10% invoice');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=5 LIMIT 1), 'Stage 2.1', 'OLT-408 [Task] Request week-18 inputs by week 16: Amazon SP-API, Flipkart, Myntra, e-invoice/e-way GSP', '2027-02-23', '2027-03-01', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S8 (wk 16) &middot; <strong>Epic:</strong> Stage 2.1 - Inventory &amp; QR warehouse</p><p><strong>Depends on:</strong> OLT-113</p><h4>User story</h4><p>As the project manager, I want week-18 credentials requested 10 working days ahead, so that Stage 2.3 is not blocked.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Marketplace credentials requested</li><li>&#9744; GSP sandbox and live credentials requested</li><li>&#9744; Requests dated and logged</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-408 [Task] Request week-18 inputs by week 16: Amazon SP-API, Flipkart, Myntra, e-invoice/e-way GSP');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=5 LIMIT 1), 'Stage 2.1', 'OLT-409 [Task] Switch stock and dispatch ownership per ADR-0001 when Odoo stock retires', '2027-03-09', '2027-03-15', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S9 (wk 18) &middot; <strong>Epic:</strong> Stage 2.1 - Inventory &amp; QR warehouse</p><p><strong>Depends on:</strong> OLT-109, OLT-406</p><h4>User story</h4><p>As an Oltao operations user, I want a clear owner for stock and dispatch from week 20, so that two systems never deduct the same stock.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Ownership table applied</li><li>&#9744; Odoo dispatch without stock handled as agreed</li><li>&#9744; Ops team briefed</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-409 [Task] Switch stock and dispatch ownership per ADR-0001 when Odoo stock retires');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=5 LIMIT 1), 'Stage 2.1', 'OLT-410 [Milestone] M4 Inventory and QR warehouse - delivered wk 18, accepted wk 20, raise 8% invoice', '2027-03-09', '2027-03-29', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S9-S10 (wk 18-20) &middot; <strong>Epic:</strong> Stage 2.1 - Inventory &amp; QR warehouse</p><p><strong>Depends on:</strong> OLT-407</p><h4>User story</h4><p>As the account manager, I want Milestone 4 accepted, so that 8% is invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Full QR cycle passes</li><li>&#9744; Opening stock matches</li><li>&#9744; Live stock on store</li><li>&#9744; 8% invoice raised</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-410 [Milestone] M4 Inventory and QR warehouse - delivered wk 18, accepted wk 20, raise 8% invoice');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=6 LIMIT 1), 'Stage 2.2', 'OLT-507 [Milestone] M5 Supply chain - delivered wk 20, accepted wk 22, raise 7% invoice', '2027-03-23', '2027-04-12', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S10-S11 (wk 20-22) &middot; <strong>Epic:</strong> Stage 2.2 - Purchase &amp; dispatch</p><p><strong>Depends on:</strong> OLT-506</p><h4>User story</h4><p>As the account manager, I want Milestone 5 accepted, so that 7% is invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; PO -&gt; stock, SO -&gt; dispatch, return -&gt; stock pass</li><li>&#9744; 7% invoice raised</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-507 [Milestone] M5 Supply chain - delivered wk 20, accepted wk 22, raise 7% invoice');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=7 LIMIT 1), 'Stage 2.3', 'OLT-610 [Task] Request week-23 bank access (API or statement import) by week 21', '2027-03-30', '2027-04-05', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S11 (wk 21) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want bank access requested early, so that Stage 3.1 bank reconciliation is not blocked.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Bank API or statement format requested</li><li>&#9744; Request dated and logged</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-610 [Task] Request week-23 bank access (API or statement import) by week 21');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=7 LIMIT 1), 'Stage 2.3', 'OLT-611 [Task] Request week-26 inputs by week 24: Meta Lead Ads and MyOperator', '2027-04-13', '2027-04-19', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S12 (wk 23) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want CRM credentials requested early, so that Stage 3.2 is not blocked.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Meta Lead Ads access requested</li><li>&#9744; MyOperator API credentials requested</li><li>&#9744; Requests dated and logged</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-611 [Task] Request week-26 inputs by week 24: Meta Lead Ads and MyOperator');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=7 LIMIT 1), 'Stage 2.3', 'OLT-612 [Task] GST adviser review of e-invoice, e-way bill and multi-GSTIN test cases', '2027-04-06', '2027-04-19', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S11-S12 (wk 22-23) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> OLT-603, OLT-604</p><h4>User story</h4><p>As the accountant, I want a GST adviser to review test cases, so that tax errors (our liability under Cl. 21.3) are caught.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Test cases reviewed and signed by adviser</li><li>&#9744; Edge cases: cancellation, credit note, inter-state</li><li>&#9744; Findings fixed</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-612 [Task] GST adviser review of e-invoice, e-way bill and multi-GSTIN test cases');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=7 LIMIT 1), 'Stage 2.3', 'OLT-613 [Milestone] M6 Billing, selling and channels - delivered wk 25, accepted wk 27, raise 10% invoice', '2027-04-27', '2027-05-17', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S13-S14 (wk 25-27) &middot; <strong>Epic:</strong> Stage 2.3 - Billing &amp; sales channels</p><p><strong>Depends on:</strong> OLT-609</p><h4>User story</h4><p>As the account manager, I want Milestone 6 accepted, so that 10% is invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; E-invoice + e-way per GSTIN</li><li>&#9744; One order per marketplace</li><li>&#9744; Dealer full flow</li><li>&#9744; 10% invoice raised</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-613 [Milestone] M6 Billing, selling and channels - delivered wk 25, accepted wk 27, raise 10% invoice');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=8 LIMIT 1), 'Stage 3.1', 'OLT-708 [Decision] Decide accounting engine: native ERP vs Zoho/Tally integration', '2027-04-20', '2027-05-04', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Decision &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S12-S13 (wk 24-26) &middot; <strong>Epic:</strong> Stage 3.1 - Accounting &amp; finance</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the project manager, I want the accounting engine decided before Stage 3.1, so that the team builds the right thing.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Options compared with client CA</li><li>&#9744; Decision recorded as ADR</li><li>&#9744; Scope impact noted</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-708 [Decision] Decide accounting engine: native ERP vs Zoho/Tally integration');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=8 LIMIT 1), 'Stage 3.1', 'OLT-709 [Task] Retire the daily accounts export to Odoo (week 30)', '2027-05-25', '2027-06-07', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 2 pts &middot; <strong>Sprint:</strong> S15 (wk 29-30) &middot; <strong>Epic:</strong> Stage 3.1 - Accounting &amp; finance</p><p><strong>Depends on:</strong> OLT-706</p><h4>User story</h4><p>As an Oltao operations user, I want the accounts export switched off once books run in the ERP, so that Odoo is fully retired from finance.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Accounts-export switch turned off</li><li>&#9744; Last export reconciled</li><li>&#9744; Client confirms</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-709 [Task] Retire the daily accounts export to Odoo (week 30)');
