INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=9 LIMIT 1), 'Stage 3.2', 'OLT-809 [Milestone] M8 CRM, warranty and service - delivered wk 33, accepted wk 35, raise 10% invoice', '2027-06-22', '2027-07-12', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S17-S18 (wk 33-35) &middot; <strong>Epic:</strong> Stage 3.2 - CRM, warranty &amp; service</p><p><strong>Depends on:</strong> OLT-808</p><h4>User story</h4><p>As the account manager, I want Milestone 8 accepted, so that 10% is invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Meta lead auto-lands</li><li>&#9744; Unified customer view</li><li>&#9744; Dealer warranty activation</li><li>&#9744; 10% invoice raised</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-809 [Milestone] M8 CRM, warranty and service - delivered wk 33, accepted wk 35, raise 10% invoice');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=10 LIMIT 1), 'Stage 3.3', 'OLT-908 [Task] Hindi translation review of manuals and warehouse/technician screens', '2027-07-06', '2027-07-19', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S18 (wk 35-36) &middot; <strong>Epic:</strong> Stage 3.3 - Hardening, handover &amp; Final Acceptance</p><p><strong>Depends on:</strong> OLT-904</p><h4>User story</h4><p>As a Hindi-speaking user, I want screens and manuals reviewed by a translator, so that wording is natural.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Translator review of lang/hi</li><li>&#9744; Manual Hindi review</li><li>&#9744; Fixes applied</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-908 [Task] Hindi translation review of manuals and warehouse/technician screens');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=10 LIMIT 1), 'Stage 3.3', 'OLT-909 [Milestone] M9 Final Acceptance - delivered wk 36, accepted wk 38, raise 10% invoice', '2027-07-20', '2027-08-02', 'Hard', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Milestone &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S19 (wk 37-38) &middot; <strong>Epic:</strong> Stage 3.3 - Hardening, handover &amp; Final Acceptance</p><p><strong>Depends on:</strong> OLT-907</p><h4>User story</h4><p>As the account manager, I want Final Acceptance signed, so that 10% is invoiced.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Final Acceptance certificate signed</li><li>&#9744; 10% invoice raised</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-909 [Milestone] M9 Final Acceptance - delivered wk 36, accepted wk 38, raise 10% invoice');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=11 LIMIT 1), 'Warranty, retention & AMC', 'OLT-1003 [Task] Provider API and GST-law updates during warranty (Cl. 17.2)', '2027-08-03', '2027-11-01', 'Medium', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 3 pts &middot; <strong>Sprint:</strong> S20-S26 (wk 39-51) &middot; <strong>Epic:</strong> Warranty, retention &amp; AMC</p><p><strong>Depends on:</strong> none</p><h4>User story</h4><p>As the client, I want provider API and GST-law changes applied during warranty, so that integrations keep working.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Monthly check of Razorpay, Cashfree, carriers, marketplaces, GSP changes</li><li>&#9744; GST rule changes applied</li><li>&#9744; Change log shared</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-1003 [Task] Provider API and GST-law updates during warranty (Cl. 17.2)');
INSERT INTO daily_tasks (project_id, phase_id, module, task_title, start_date, end_date, priority, status, employee_id, assigned_by, description, created_at, updated_at) SELECT @p, (SELECT id FROM project_phases WHERE project_id=@p AND sort_order=11 LIMIT 1), 'Warranty, retention & AMC', 'OLT-1004 [Task] Quarterly backup restore test', '2027-08-03', '2027-11-01', 'Low', 'Pending', @emp, @usr, '<p><strong>Type:</strong> Task &middot; <strong>Estimate:</strong> 1 pts &middot; <strong>Sprint:</strong> S20-S26 (wk 39-51) &middot; <strong>Epic:</strong> Warranty, retention &amp; AMC</p><p><strong>Depends on:</strong> OLT-906</p><h4>User story</h4><p>As DevOps, I want a restore test each quarter, so that backups are proven.</p><h4>Acceptance criteria</h4><ul><li>&#9744; Restore test done and logged</li><li>&#9744; Issues fixed</li></ul><h4>Definition of done</h4><p>Code reviewed, tests green, documented, deployed to staging with masked data (Cl. 13.4), committed to the client repository (Cl. 11.5). New scope only via signed Change Request (Cl. 10.2).</p>', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM daily_tasks x WHERE x.project_id=@p AND x.task_title='OLT-1004 [Task] Quarterly backup restore test');

-- 3. sprint plan on each phase (replaces the phase description with the local one)
UPDATE project_phases SET description='<p><strong>Goal:</strong> Sign a contract we can deliver, set up client-owned accounts and a clean codebase before week 1.</p><p><strong>Window &amp; payment:</strong> Before week 1 · Milestone 0 Signing = 10% (Roadmap) / 15% advance (draft Agreement 8.2).</p><h4>Scope</h4><ul><li>Settle the 7 contract points in the delivery plan (section 4) plus the roadmap\'s 12 open points</li><li>Attach Roadmap v1.1 as a Schedule or replace Schedule B (draft Schedule B keeps Shopify live to the last milestone, Clause 6.2)</li><li>List pre-existing platform code in Schedule A with a licence (Clause 11.3)</li><li>Fill Schedules D (input dates), E (rate card) and F (key personnel); set the Contract Price incl. on-call and warranty</li><li>Client-owned GitHub, cloud, DNS and secrets vault (Clauses 11.5, 12.1, 12.2)</li><li>Scope clean-up: SaaS layer removed, HRMS removed or hidden before first push</li></ul><h4>Client inputs due</h4><ul><li>Proposal v3 (Annexure 1)</li><li>Kickoff date, peak sales months, accounting opening-balance date</li><li>Client Project Manager name (Schedule F)</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>✅ Single-client mode: SaaS layer removed, oltao tenant pinned</li><li>☐ Agreement signed with roadmap attached and Schedule A tools listed</li><li>☐ Client repository created; code pushed; commits daily from now on</li><li>☐ Every team member signed confidentiality + IP undertaking (Clause 19.5)</li><li>☐ CI runs tests, static analysis and licence check (Clause 11.4)</li><li>☐ Clean build deploys to staging from the client repository</li></ul><h4>Notes / risks</h4><ul><li>Draft Agreement: delay damages 2.5%/week up to 10%; termination after 4 weeks\' delay or 3 failed UATs</li><li>Clause 20.3: every input must be requested in writing 10 working days ahead or the delay is ours</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>27 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S0</td><td>Pre-kickoff</td><td>OLT-001, OLT-002, OLT-003, OLT-004, OLT-005, OLT-006, OLT-007, OLT-008, OLT-009, OLT-010</td></tr><tr><td>S1</td><td>10 Nov - 23 Nov 2026 (wk 1-2)</td><td>OLT-011</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=1;
UPDATE project_phases SET description='<p><strong>Goal:</strong> Lock requirements, architecture, API contract, migration and test plan, and get every document signed.</p><p><strong>Window &amp; payment:</strong> Weeks 1-3 · Payment Milestone 1 Design sign-off = 5% (delivered wk 3, accepted wk 5).</p><h4>Scope</h4><ul><li>Audit every Shopify call in the Next.js repo and the 22 Shopify apps</li><li>Architecture, database schema, OpenAPI storefront contract</li><li>DPDP design (consent, retention, processor role, 6-hour breach notice)</li><li>Shopify + Odoo migration map and rollback plan (Clause 15.2)</li><li>Test plan, wireframes for new screens, input-request calendar</li><li>Decisions: ADR-0001 interim invoicing owner, store GSTIN + series, API p95 target, blogs source, 3D model hosting, marketplace stock push</li></ul><h4>Client inputs due</h4><ul><li>Razorpay, Cashfree, OTP, email, WhatsApp, Meta / GA4 / Google Ads access - due week 3</li><li>VMS vendor API decision - due week 4</li><li>One approver per module area</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9989; Every Shopify call mapped to an ERP endpoint</li><li>&#9989; OpenAPI storefront contract + Postman collection</li><li>&#9744; Architecture and schema document signed</li><li>&#9744; DPDP design signed</li><li>&#9744; Migration map + rollback plan signed</li><li>&#9744; Test plan signed</li><li>&#9744; Ownership table for stock/dispatch/billing weeks 14-27 agreed (ADR-0001)</li><li>&#9744; Design sign-off certificate received</li></ul><h4>Notes / risks</h4><ul><li>Weeks 20-27 have no clear owner for stock and dispatch - agree ownership table now</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>46 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S1</td><td>10 Nov - 23 Nov 2026 (wk 1-2)</td><td>OLT-101, OLT-102, OLT-103, OLT-104, OLT-105, OLT-106, OLT-107, OLT-108, OLT-109, OLT-110, OLT-112, OLT-113, OLT-114, OLT-115</td></tr><tr><td>S2</td><td>24 Nov - 07 Dec 2026 (wk 3-4)</td><td>OLT-111, OLT-116</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=2;
UPDATE project_phases SET description='<p><strong>Goal:</strong> Run oltao.in fully on the ERP API in staging, with every payment method and conversion tracking working.</p><p><strong>Window &amp; payment:</strong> Weeks 4-9 · Payment Milestone 2 Storefront APIs ready = 12% (delivered wk 9, accepted wk 11).</p><h4>Scope</h4><ul><li>Catalogue (variants, specs, collections, SEO, facet filters), cart, coupons</li><li>Checkout: GST, shipping, COD, partial COD, EMI/BNPL; Razorpay + Cashfree</li><li>Customer OTP accounts, orders, GST invoice, packing slip</li><li>Email/WhatsApp alerts; staff RBAC + 2FA + audit log</li><li>Rate limit, bot and fraud checks; daily backups</li><li>Interim Odoo stock; Meta Pixel + CAPI, GA4, Google Ads, feeds with the same IDs</li></ul><h4>Client inputs due</h4><ul><li>Cashfree test keys</li><li>Shipping charge rules (decision D7)</li><li>Store GSTIN state confirmation</li><li>Odoo API, carriers, auditor - due week 8</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; Storefront fully on ERP API in staging</li><li>&#9744; Test order through every payment method</li><li>&#9744; Meta and Google conversions verified; feed IDs unchanged</li><li>&#9744; Storefront API p95 under target (500 ms contract)</li><li>&#9744; Release pack: notes, test results, acceptance checklist</li></ul><h4>Notes / risks</h4><ul><li>Known storefront bug: card links to /products/undefined?id=undefined</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>138 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S2</td><td>24 Nov - 07 Dec 2026 (wk 3-4)</td><td>OLT-201, OLT-202, OLT-203, OLT-207, OLT-222</td></tr><tr><td>S3</td><td>08 Dec - 21 Dec 2026 (wk 5-6)</td><td>OLT-204, OLT-205, OLT-206, OLT-208, OLT-209, OLT-210, OLT-211, OLT-219, OLT-220, OLT-224, OLT-225</td></tr><tr><td>S4</td><td>22 Dec - 04 Jan 2027 (wk 7-8)</td><td>OLT-212, OLT-213, OLT-214, OLT-215, OLT-216, OLT-221, OLT-223</td></tr><tr><td>S5</td><td>05 Jan - 18 Jan 2027 (wk 9-10)</td><td>OLT-217, OLT-218, OLT-226</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=3;
UPDATE project_phases SET description='<p><strong>Goal:</strong> Move live oltao.in orders from Shopify to the ERP with no data loss and a tested rollback.</p><p><strong>Window &amp; payment:</strong> Weeks 10-15 · Cutover in week 14 (max 2 h downtime) · Payment Milestone 3 = 10% (delivered wk 14, accepted wk 15).</p><h4>Scope</h4><ul><li>Migration tools with 2 dry runs + reconciliation (counts and money totals)</li><li>Shiprocket, ShadowFox, Delivery One with manual AWB fallback</li><li>Odoo bridge: stock in, orders out, daily accounts export (3 separate switches)</li><li>Customer dashboard v1, 301 redirects, load test at 5x peak</li><li>2-week parallel run (wk 12-13) with automatic order comparison</li><li>CERT-In VAPT, rollback rehearsal, on-call rota from week 14</li></ul><h4>Client inputs due</h4><ul><li>Shopify and Odoo full exports</li><li>Carrier API keys, Odoo API, CERT-In auditor (week 8)</li><li>Agreed low-traffic cutover window in writing</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; Every Shopify call mapped; staging storefront on ERP with migrated data</li><li>&#9744; Two migration dry runs; counts and money totals match</li><li>&#9744; Meta/Google purchase and add-to-cart events verified; feed IDs unchanged</li><li>&#9744; Two-week parallel run: price, tax, shipping, payment status match per order</li><li>&#9744; CERT-In Critical/High findings fixed</li><li>&#9744; Switch in low-traffic window; final delta migrated; 301s live</li><li>&#9744; Rollback ready: storefront can repoint to Shopify; Shopify kept 30 days</li><li>&#9744; Daily checks for two weeks; customers log in by OTP; old orders visible</li><li>&#9744; Reconciliation report signed; no Critical/Major open 7 days after cutover</li></ul><h4>Notes / risks</h4><ul><li>Book VAPT to finish by mid week 12 with a retest slot in week 13</li><li>Support SLAs (Schedule C) apply from week 14 - on-call rota needed</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>96 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S5</td><td>05 Jan - 18 Jan 2027 (wk 9-10)</td><td>OLT-301, OLT-302, OLT-303, OLT-305, OLT-306</td></tr><tr><td>S6</td><td>19 Jan - 01 Feb 2027 (wk 11-12)</td><td>OLT-304, OLT-307, OLT-308, OLT-309, OLT-310, OLT-311</td></tr><tr><td>S7</td><td>02 Feb - 15 Feb 2027 (wk 13-14)</td><td>OLT-312, OLT-313, OLT-314, OLT-315, OLT-316, OLT-317</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=4;
UPDATE project_phases SET description='<p><strong>Goal:</strong> One multi-warehouse stock ledger driven by QR scans, feeding live stock to the store.</p><p><strong>Window &amp; payment:</strong> Weeks 16-18 · Payment Milestone 4 = 8% (delivered wk 18, accepted wk 20). Stock bridge from Odoo retires.</p><h4>Scope</h4><ul><li>Storage locations down to drawer, rack, shelf and bin</li><li>QR codes per item, batch and bin; label printing</li><li>Mobile scan screens in Hindi and English</li><li>Low-stock alerts, live storefront availability, count reconciliation</li><li>Opening stock load</li></ul><h4>Client inputs due</h4><ul><li>Signed physical stock count</li><li>Label printer model</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; Full receive-to-dispatch cycle by QR scan</li><li>&#9744; Opening stock matches signed count</li><li>&#9744; Live stock showing on store</li><li>&#9744; Odoo stock bridge switched off</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>43 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S8</td><td>16 Feb - 01 Mar 2027 (wk 15-16)</td><td>OLT-401, OLT-402, OLT-403, OLT-408</td></tr><tr><td>S9</td><td>02 Mar - 15 Mar 2027 (wk 17-18)</td><td>OLT-404, OLT-405, OLT-406, OLT-407, OLT-409, OLT-410</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=5;
UPDATE project_phases SET description='<p><strong>Goal:</strong> Supply chain in the ERP: purchase to stock, sales to dispatch, returns back to stock.</p><p><strong>Window &amp; payment:</strong> Weeks 19-20 · Payment Milestone 5 Supply chain = 7% (delivered wk 20, accepted wk 22).</p><h4>Scope</h4><ul><li>Suppliers, PO, GRN with QR scan-in, bills, purchase returns</li><li>Transfers, allocation, pick lists, dispatch</li><li>Courier and customer returns</li><li>Reorder suggestions</li></ul><h4>Client inputs due</h4><ul><li>Supplier master</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; PO -> GRN -> bill -> stock</li><li>&#9744; SO -> allocation -> pick -> dispatch</li><li>&#9744; Return restores stock correctly</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>28 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S10</td><td>16 Mar - 29 Mar 2027 (wk 19-20)</td><td>OLT-501, OLT-502, OLT-503, OLT-504, OLT-505, OLT-506, OLT-507</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=6;
UPDATE project_phases SET description='<p><strong>Goal:</strong> Compliant billing per GSTIN, marketplaces and dealers in one order queue; Odoo billing retires.</p><p><strong>Window &amp; payment:</strong> Weeks 21-25 · Payment Milestone 6 = 10% (delivered wk 25, accepted wk 27).</p><h4>Scope</h4><ul><li>Quote -> SO -> invoice chain, credit notes</li><li>E-invoice IRN and e-way bill, multi-GSTIN series and consolidated views</li><li>Trade accounts with PO billing and credit terms</li><li>Amazon, Flipkart, Myntra order sync and channel reports</li><li>Dealer portal (OTP login, verification, bulk order, dashboard)</li></ul><h4>Client inputs due</h4><ul><li>Amazon SP-API, Flipkart, Myntra seller API, IRP/e-way API per GSTIN - due week 18</li><li>Dealer master list</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; E-invoice + e-way bill for each GSTIN</li><li>&#9744; One order from each marketplace in the queue</li><li>&#9744; Dealer full journey</li><li>&#9744; Odoo order bridge and billing retired</li></ul><h4>Notes / risks</h4><ul><li>Amazon listing map, FBA warehouse and report upload already built ahead of plan</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>76 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S11</td><td>30 Mar - 12 Apr 2027 (wk 21-22)</td><td>OLT-601, OLT-602, OLT-603, OLT-604, OLT-606, OLT-610, OLT-612</td></tr><tr><td>S12</td><td>13 Apr - 26 Apr 2027 (wk 23-24)</td><td>OLT-605, OLT-607, OLT-611</td></tr><tr><td>S13</td><td>27 Apr - 10 May 2027 (wk 25-26)</td><td>OLT-608, OLT-609, OLT-613</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=7;
UPDATE project_phases SET description='<p><strong>Goal:</strong> Separate books per entity with automatic postings, approved by the client\'s CA.</p><p><strong>Window &amp; payment:</strong> Weeks 26-28 · Payment Milestone 7 = 8% (delivered wk 28, accepted wk 30). Daily accounts export retires week 30.</p><h4>Scope</h4><ul><li>Chart of accounts, vouchers, auto-posting + recovery queue</li><li>Bank reconciliation, assets, budgets, statements</li><li>GSTR-1 / 3B, multi-currency</li><li>Edit log that cannot be disabled; India-hosted backups (Clause 4.8)</li></ul><h4>Client inputs due</h4><ul><li>Bank statement access / API - due week 23</li><li>CA-approved chart of accounts and opening balances</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; Opening balances match</li><li>&#9744; One month replay posts cleanly</li><li>&#9744; One month-end parallel close signed by CA</li><li>&#9744; Tally/Excel export and read-only CA login</li></ul><h4>Notes / risks</h4><ul><li>Decision: native engine vs Zoho/Tally integration</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>41 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S12</td><td>13 Apr - 26 Apr 2027 (wk 23-24)</td><td>OLT-708</td></tr><tr><td>S13</td><td>27 Apr - 10 May 2027 (wk 25-26)</td><td>OLT-701, OLT-702</td></tr><tr><td>S14</td><td>11 May - 24 May 2027 (wk 27-28)</td><td>OLT-703, OLT-704, OLT-705, OLT-706, OLT-707, OLT-710</td></tr><tr><td>S15</td><td>25 May - 07 Jun 2027 (wk 29-30)</td><td>OLT-709</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=8;
UPDATE project_phases SET description='<p><strong>Goal:</strong> One customer view across leads, orders, warranty, installation and support; Odoo retires.</p><p><strong>Window &amp; payment:</strong> Weeks 29-33 · Payment Milestone 8 = 10% (delivered wk 33, accepted wk 35).</p><h4>Scope</h4><ul><li>Leads from web, WhatsApp, Meta Lead Ads; pipeline</li><li>Warranty and activation (dealer-sold and store-sold)</li><li>Installation and technician assignment (VMS or native, Clause 2.4)</li><li>Tickets, journeys, MyOperator</li><li>Full customer dashboard</li></ul><h4>Client inputs due</h4><ul><li>Meta Lead Ads permission and MyOperator key - due week 26</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; Meta lead lands automatically</li><li>&#9744; Unified customer view</li><li>&#9744; Dealer warranty activation</li><li>&#9744; CRM and warranty data migrated; Odoo retired</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>53 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S15</td><td>25 May - 07 Jun 2027 (wk 29-30)</td><td>OLT-801, OLT-802, OLT-803</td></tr><tr><td>S16</td><td>08 Jun - 21 Jun 2027 (wk 31-32)</td><td>OLT-804, OLT-805, OLT-806</td></tr><tr><td>S17</td><td>22 Jun - 05 Jul 2027 (wk 33-34)</td><td>OLT-807, OLT-808, OLT-809</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=9;
UPDATE project_phases SET description='<p><strong>Goal:</strong> Secure, documented, trained and handed over; Final Acceptance in week 38.</p><p><strong>Window &amp; payment:</strong> Weeks 34-36 build, Final Acceptance week 38 · Payment Milestone 9 = 10%.</p><h4>Scope</h4><ul><li>Full security and performance tests</li><li>Dashboards</li><li>Technical, API, schema, deployment docs; admin and user manuals in English and Hindi</li><li>Training</li><li>Credential handover, backup restore test</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; All milestones accepted</li><li>&#9744; Parallel run complete; migration reconciliation signed</li><li>&#9744; VAPT: no open Critical or High</li><li>&#9744; All documentation and credentials handed over (Clause 9.5)</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>43 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S17</td><td>22 Jun - 05 Jul 2027 (wk 33-34)</td><td>OLT-901, OLT-902, OLT-903, OLT-904</td></tr><tr><td>S18</td><td>06 Jul - 19 Jul 2027 (wk 35-36)</td><td>OLT-905, OLT-906, OLT-908</td></tr><tr><td>S19</td><td>20 Jul - 02 Aug 2027 (wk 37-38)</td><td>OLT-907, OLT-909</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=10;
UPDATE project_phases SET description='<p><strong>Goal:</strong> Keep the system healthy after Go-Live and collect retention.</p><p><strong>Window &amp; payment:</strong> Retention 10% about week 51 (90 days after Go-Live) · Warranty 10 months from Go-Live · AMC optional at 8%/year.</p><h4>Scope</h4><ul><li>Free defect fixes within Schedule C times</li><li>Provider API and GST/e-invoice law updates (Clause 17.2)</li><li>99.5% monthly uptime of storefront API and checkout</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; No Critical or Major defect open at day 90</li><li>&#9744; Retention invoice raised</li><li>&#9744; AMC proposal sent before warranty ends</li></ul><h4>Sprint plan</h4><p>Two-week sprints from kickoff 10 Nov 2026. Tickets are listed by the sprint they start in. Total estimate: <strong>7 pts</strong>.</p><table><thead><tr><th>Sprint</th><th>Dates</th><th>Tickets starting</th></tr></thead><tbody><tr><td>S20</td><td>03 Aug - 16 Aug 2027 (wk 39-40)</td><td>OLT-1001, OLT-1003, OLT-1004</td></tr><tr><td>S26</td><td>26 Oct - 08 Nov 2027 (wk 51-52)</td><td>OLT-1002</td></tr></tbody></table>', updated_at=NOW() WHERE project_id=@p AND sort_order=11;

